    # Spread rows (have 2s inside): rows 1,2,3,4, 7,8, 10,11, 13,14, 16,17,18,19, 21,22,23
    # Narrow rows: row 0, 5, 6, 9, 12, 15, 20

    row = []
    for c in range(width):
        is_border = (c % 6 == 0)  # cols 0, 6, 12, 18, 24

        if pos_in_unit == 0:
            # Row 0: 7s at 18, 24
            if c == 18 or c == 24:
                row.append(7)
            elif is_border:
                row.append(3)
            else:
                row.append(3)
        elif pos_in_unit == 5:
            # Row 5: 6 at 0,6 but 7 stays at 18,24
            if c == 0:
                row.append(6)
            elif c == 6:
                row.append(6)
            elif c == 18 or c == 24:
                row.append(7)
            else:
                row.append(3)
        elif pos_in_unit == 1:
            # Row 6: like row 5
            if c == 0:
                row.append(6)
            elif c == 6:
                row.append(6)
            elif is_border:
                row.append(3)
            else:
                row.append(3)
        elif pos_in_unit == 2:
            # Row 9: 6 at 0,6 but all others 3
            if c == 0:
                row.append(6)
            elif c == 6:
                row.append(6)
            else:
                row.append(3)
        elif pos_in_unit == 3 or pos_in_unit == 4:
            # Standard row in unit (rows 1-4): 3 at borders, 2 inside
            if is_border:
                row.append(3)
            else:
                row.append(2)
        elif pos_in_unit == 5 or pos_in_unit == 0:
            # Bottom special rows in unit (rows 12, 15, 20): 1 at 6,12; 8 at 18,24
            if c in [6, 12]:
                row.append(1)
            elif c in [18, 24]:
                row.append(8)
            elif is_border:
                row.append(3)
            else:
                row.append(3)
        else:
            # Catch-all: standard row
            if is_border:
                row.append(3)
            else:
                row.append(2)

    return row

